// 默认纯数据入口保原完整调用，不查询新增 Reflect 或拒绝回调。
if (!mayCommit) {
  (skill.history as Extract<MechanicalSkill, { kind: "inspection" }>["history"]).push({
    day,
    targetId: target.id,
    result: { ...result },
  });
  return;
}
// 受控首写保 history→push callee→target.id→result spread，再复验；使用原 history receiver。

test("默认查验数据入口不读取 Reflect，原 push receiver 与参数 getter 错误保持", () => {
  const originalApply = Object.getOwnPropertyDescriptor(Reflect, "apply")!;
  const trace: string[] = [], history: unknown[] = [], originalError = new Error("inspection_target_original");
  let receiver: unknown, thrown: unknown, failTarget = false;
  const reports: Array<{ day: number; targetId: number; result: { kind: "role"; role: Role } }> = [];
  Object.defineProperty(reports, "push", { configurable: true,
    get() {
      trace.push("push");
      return function(this: unknown, row: unknown) { receiver = this; history.push(row); trace.push("append"); return 1; };
    },
  });
  const skill = { kind: "inspection" as const, get history() { trace.push("history"); return reports; } };
  const target = { get id() { trace.push("target"); if (failTarget) throw originalError; return 5; } };
  const result = { kind: "role" as const, get role() { trace.push("result"); return Role.Hunter; } };
  Object.defineProperty(Reflect, "apply", { configurable: true,
    get() { trace.push("unexpected-reflect"); throw new Error("default_reflect_must_not_read"); },
  });
  try {
    recordMechanicalInspection(skill, 2, target, result);
    failTarget = true;
    try { recordMechanicalInspection(skill, 2, target, result); } catch (error) { thrown = error; }
  } finally { Object.defineProperty(Reflect, "apply", originalApply); }
  expect(trace).toEqual(["history", "push", "target", "result", "append", "history", "push", "target"]);
  expect(receiver).toBe(reports);
  expect(history).toEqual([{ day: 2, targetId: 5, result: { kind: "role", role: Role.Hunter } }]);
  expect(thrown).toBe(originalError);
});
